def variantlarni_kochir(apps, schema_editor):
    """Eski variant_a/b/c maydonlarini yangi Variant jadvaliga ko'chiradi."""
    Savol = apps.get_model('home', 'Savol')
    Variant = apps.get_model('home', 'Variant')

    yangi = []
    for savol in Savol.objects.all():
        for i, harf in enumerate('abc', start=1):
            yangi.append(Variant(
                savol=savol,
                order=i,
                matn=getattr(savol, f'variant_{harf}'),
                togri=(savol.togri_javob == harf),
            ))
    Variant.objects.bulk_create(yangi)


def variantlarni_qaytar(apps, schema_editor):
    Savol = apps.get_model('home', 'Savol')
    Variant = apps.get_model('home', 'Variant')

    for savol in Savol.objects.all():
        variantlar = list(Variant.objects.filter(savol=savol).order_by('order')[:3])
        for harf, v in zip('abc', variantlar):
            setattr(savol, f'variant_{harf}', v.matn)
            if v.togri:
                savol.togri_javob = harf
        savol.save()
    Variant.objects.all().delete()


